package product

import (
	"strings"

	"github.com/olivere/elastic/v7"
)

// OfficeLinkSort - godoc
func OfficeLinkSort(sort string) (fieldSorts []elastic.Sorter) {
	//다중 정렬 조건 ex) 1|2,3|1
	commaArray := strings.Split(sort, ",")

	for _, commaValue := range commaArray {

		barArray := strings.Split(commaValue, "|")
		// |

		if len(barArray) == 2 {
			fieldSort := "popularityScore"

			if barArray[0] == "1" {
				fieldSort = "registerDateTime"
			} else if barArray[0] == "2" {
				fieldSort = "shopCode"
			} else if barArray[0] == "3" {
				fieldSort = "lowestPrice"
			} else if barArray[0] == "4" {
				fieldSort = "deliveryPrice"
			} else if barArray[0] == "5" {
				fieldSort = "shopProductCode"
			} else if barArray[0] == "6" {
				fieldSort = "productName.field"
			} else if barArray[0] == "7" {
				fieldSort = "productMaker.field"
			} else if barArray[0] == "8" {
				fieldSort = "modifyDateTime"
			} else if barArray[0] == "9" {
				fieldSort = "orderCount.field"
			} else if barArray[0] == "10" {
				fieldSort = "totalOrderPrice.field"
			} else if barArray[0] == "11" {
				fieldSort = "memberPrice"
			} else {
				fieldSort = "popularityScore"
			}

			if barArray[1] == "1" {
				fieldSorts = append(fieldSorts, elastic.NewFieldSort(fieldSort).Asc())
			} else if barArray[1] == "2" {
				fieldSorts = append(fieldSorts, elastic.NewFieldSort(fieldSort).Desc())
			} else {
				fieldSorts = append(fieldSorts, elastic.NewFieldSort(fieldSort).Asc())
			}
		}
	}
	return
}

// OfficeUnlinkSort - godoc
func OfficeUnlinkSort(sort string) (fieldSorts []elastic.Sorter) {
	//다중 정렬 조건 ex) 1|2,3|1
	commaArray := strings.Split(sort, ",")

	for _, commaValue := range commaArray {

