	return
}

// ProductListSort 상품 리스트 정렬 - FASTCAT-1055 (상품리스트 정렬조건 참조)
func ProductListSort(sort string) (fieldSorts []elastic.Sorter, reCheck bool, brpsFieldName string) {

	// 상품의견 카운트(WRITECNT) 경우에는 묶음대표 상품설정(BRPS) 변경을 하지 않는다.
	// brpsFieldName 를 SKIP 로 리턴
	/*
		[FASTCAT-1055] ‘우선순위‘ 설정 카테고리 대표상품 정렬 기준 변경 요청
		인기상품순일 때만 다르고 나머지는 '인기순위', '우선순위' 설정 카테고리 정렬동일하게 처리.
	*/
	//다중 정렬 조건 ex) 1|2,3|1
	commaArray := strings.Split(sort, ",") // 7|1,3|1,2|2
	reCheck = true
	brpsFieldName = "SKIP"
	//,
	for idx, commaValue := range commaArray {

		barArray := strings.Split(commaValue, "|")
		// |

		if len(barArray) == 2 {

			if barArray[0] == "7" {
				if barArray[1] == "2" {
					barArray[1] = "1"
				} else {
					barArray[1] = "2"
				}
			}

			fieldSort := "savePlusQ"

			if barArray[0] == "1" {
				fieldSort = "savePlusQ" // 수동 인기순위값 + 인기순위점수 (TSAVE_PLUS.SAVE_PLUS_Q + TPRODUCTCATEGORY.NCNTSAVE)
			} else if barArray[0] == "2" {
				//[FASTCAT-1266] 상품리스트 키워드 검색 가중치 추가 건
				//상품리스트 결과내 검색 시 가중치 점수 적용
				if barArray[1] == "1" {
					fieldSorts = append(fieldSorts, elastic.NewFieldSort("_score").Asc())
				} else if barArray[1] == "2" {
					fieldSorts = append(fieldSorts, elastic.NewFieldSort("_score").Desc())
				} else {
					fieldSorts = append(fieldSorts, elastic.NewFieldSort("_score").Asc())
				}

				fieldSort = "cntSave" // 인기순위
				if idx == 0 {
					brpsFieldName = "bundleDisplaySequence"
				}
			} else if barArray[0] == "3" {
				fieldSort = "lowestPrice" //최저가 (낮은가격순3|1, 높은가격순3|2)
			} else if barArray[0] == "4" {
				fieldSort = "productCode" // 상품코드
			} else if barArray[0] == "5" {
				fieldSort = "productName.field" // 상품명
			} else if barArray[0] == "6" {
				fieldSort = "shopQuantity" // 업체수
				reCheck = false
			} else if barArray[0] == "7" {
				fieldSort = "productClassification" // 최저가 0이상
				reCheck = false
			} else if barArray[0] == "8" {
				fieldSort = "bundleName.field" // 묶음명
			} else if barArray[0] == "9" {
				fieldSort = "bundleDisplaySequence" // 묶음 조건 노출순서
			} else if barArray[0] == "10" {
				fieldSort = "productBrand.field" // 브랜드명
			} else if barArray[0] == "11" {
				fieldSort = "productMaker.field" // 제조사명
			} else if barArray[0] == "12" {
				fieldSort = "registerDateTime" // 등록일시
				// reCheck = false
			} else if barArray[0] == "13" {
				fieldSort = "firstMakeDate" // 최초제조일
				brpsFieldName = "manufactureDate"
			} else if barArray[0] == "14" {
				fieldSort = "writeCnt" // 상품의견
				reCheck = false
			} else if barArray[0] == "15" {
				fieldSort = "totalPrice" // 배송비 포함 최저가 (낮은가격순15|1, 높은가격순15|2)
			} else if barArray[0] == "16" {
				fieldSort = "unitLowPrice" // 배송비 미포함 단위 환산 최저가 (가격비교 탭에서만 노출)
				reCheck = false
			} else if barArray[0] == "17" {
				fieldSort = "unitTotalPrice" // 배송비 포함 단위 환산 최저가 (가격비교 탭에서만 노출)
				reCheck = false
			} else if barArray[0] == "18" {
				fieldSort = "memberPrice" // 배송비 미포함 멤버십 가격
				reCheck = false
			} else if barArray[0] == "19" {
				fieldSort = "memberTotalPrice" // 배송비 포함 멤버십 가격
				reCheck = false
			} else if barArray[0] == "20" {
				fieldSort = "unitMemberPrice" // 배송비 미포함 단위 환산 멤버십 가격 (가격비교 탭에서만 노출)
				reCheck = false
			} else if barArray[0] == "21" {
				fieldSort = "unitMemberTotalPrice" // 배송비 포함 단위 환산 멤버십 가격 (가격비교 탭에서만 노출)
				reCheck = false
			} else {
				fieldSort = "savePlusQ"
			}

			if barArray[1] == "1" {
				fieldSorts = append(fieldSorts, elastic.NewFieldSort(fieldSort).Asc())
			} else if barArray[1] == "2" {
				fieldSorts = append(fieldSorts, elastic.NewFieldSort(fieldSort).Desc())
			} else {
				fieldSorts = append(fieldSorts, elastic.NewFieldSort(fieldSort).Asc())
			}
		}

	}

	return fieldSorts, reCheck, brpsFieldName
}

// ProductSearchSort -  통합상품 검색 정렬
func ProductSearchSort(sort string) (fieldSorts []elastic.Sorter) {

	//golang - switch-case : break 생략 가능
	//인기순 정렬 -> popularityScore 점수는 2순위 정렬로 추가
	switch sort {
	case "1": //상품명순
		fieldSorts = append(fieldSorts, elastic.NewFieldSort("productName.field").Asc())
	case "2": //최저가순
		fieldSorts = append(fieldSorts, elastic.NewFieldSort("productClassification").Desc())
		fieldSorts = append(fieldSorts, elastic.NewFieldSort("lowestPrice").Asc())
		//raParam = "productClassification:DESC,lowestPrice:ASC"
	case "3": //최고가순
		fieldSorts = append(fieldSorts, elastic.NewFieldSort("lowestPrice").Desc())
		//raParam = "lowestPrice:DESC"
	case "4": //제조일순
		fieldSorts = append(fieldSorts, elastic.NewFieldSort("firstMakeDate").Desc())
		//fieldSorts = append(fieldSorts, elastic.NewFieldSort("manufactureDate").Desc())
		// fieldSorts = append(fieldSorts, elastic.NewFieldSort("registerDate").Desc())
		fieldSorts = append(fieldSorts, elastic.NewFieldSort("registerDateTime").Desc())
		fieldSorts = append(fieldSorts, elastic.NewFieldSort("modifyDateTime").Desc())
		//raParam = "manufactureDate:DESC"
	case "5": //배송비순
		fieldSorts = append(fieldSorts, elastic.NewFieldSort("deliveryPrice").Asc())
		//raParam = "deliveryPrice:ASC"
	case "6": //판매몰순
		fieldSorts = append(fieldSorts, elastic.NewFieldSort("shopQuantity").Desc())
		// fieldSorts = append(fieldSorts, elastic.NewFieldSort("registerDate").Desc())
		// [FASTCAT-1217] 상품리스트,통검 인기순 및 판매점순 정렬조건 변경
		fieldSorts = append(fieldSorts, elastic.NewFieldSort("_score").Desc())
		fieldSorts = append(fieldSorts, elastic.NewFieldSort("productMaker.field").Asc())
		fieldSorts = append(fieldSorts, elastic.NewFieldSort("productBrand.field").Asc())
		fieldSorts = append(fieldSorts, elastic.NewFieldSort("productName.field").Asc())
		fieldSorts = append(fieldSorts, elastic.NewFieldSort("bundleDisplaySequence").Asc())
		fieldSorts = append(fieldSorts, elastic.NewFieldSort("bundleName.field").Asc())
		//raParam = "shopQuantity:DESC,registerDate:DESC"
	case "7": //제조사순
		fieldSorts = append(fieldSorts, elastic.NewFieldSort("productMaker.field").Asc())
		//raParam = "productMaker.field:ASC"
	case "8": //상품구분(기준,검색)
		fieldSorts = append(fieldSorts, elastic.NewFieldSort("productClassification").Asc())
		//raParam = "productClassification:ASC"
	case "9": //인기순
		fieldSorts = append(fieldSorts, elastic.NewFieldSort("_score").Desc())
		fieldSorts = append(fieldSorts, elastic.NewFieldSort("popularityScore").Desc())
		// fieldSorts = append(fieldSorts, elastic.NewFieldSort("manufactureDate").Desc())
		// [FASTCAT-1217] 상품리스트,통검 인기순 및 판매점순 정렬조건 변경 - "modifyDateTime": {"copy_to": ["manufactureDateTime"]}
		fieldSorts = append(fieldSorts, elastic.NewFieldSort("manufactureDateTime").Desc())
		//raParam = "_score:DESC,registerDate:DESC"
	case "10": //상품의견 카운트순
		fieldSorts = append(fieldSorts, elastic.NewFieldSort("writeCnt").Desc())
		fieldSorts = append(fieldSorts, elastic.NewFieldSort("_score").Desc())
		//raParam = "writeCnt:DESC,_score:DESC"
	case "11": //등록일순
		fieldSorts = append(fieldSorts, elastic.NewFieldSort("registerDate").Desc())
		//raParam = "registerDate:DESC"
	case "12": //최저가순(배송비포함)
		fieldSorts = append(fieldSorts, elastic.NewFieldSort("productClassification").Desc())
		fieldSorts = append(fieldSorts, elastic.NewFieldSort("totalPrice").Asc())
		//raParam = "productClassification:DESC,totalPrice:ASC"
	case "13": //최고가순(배송비포함)
		fieldSorts = append(fieldSorts, elastic.NewFieldSort("totalPrice").Desc())
		//raParam = "totalPrice:DESC"
	case "14": //제조일순(추천정렬)
		fieldSorts = append(fieldSorts, elastic.NewFieldSort("prodType").Asc())
		fieldSorts = append(fieldSorts, elastic.NewFieldSort("manufactureDate").Desc())
		//raParam = "prodType:ASC,manufactureDate:DESC"
	case "15": //링크상품의 인기순
		fieldSorts = append(fieldSorts, elastic.NewFieldSort("_score").Desc())
		fieldSorts = append(fieldSorts, elastic.NewFieldSort("cntSave").Desc())
		fieldSorts = append(fieldSorts, elastic.NewFieldSort("manufactureDateTime").Desc())
	case "16": //멤버십 최저가순
		fieldSorts = append(fieldSorts, elastic.NewFieldSort("productClassification").Desc())
		fieldSorts = append(fieldSorts, elastic.NewFieldSort("memberPrice").Asc())
		//raParam = "productClassification:DESC,totalPrice:ASC"
	case "17": //멤버십 최고가순
		fieldSorts = append(fieldSorts, elastic.NewFieldSort("memberPrice").Desc())
	case "18": //멤버십 최저가순(배송비포함)
		fieldSorts = append(fieldSorts, elastic.NewFieldSort("productClassification").Desc())
		fieldSorts = append(fieldSorts, elastic.NewFieldSort("memberTotalPrice").Asc())
		//raParam = "productClassification:DESC,totalPrice:ASC"
	case "19": //멤버십 최고가순(배송비포함)
		fieldSorts = append(fieldSorts, elastic.NewFieldSort("memberTotalPrice").Desc())
	case "20":
		fieldSorts = append(fieldSorts, elastic.NewFieldSort("productClassification").Desc())
		fieldSorts = append(fieldSorts, elastic.NewFieldSort("unitLowPrice").Asc())
	case "21":
		fieldSorts = append(fieldSorts, elastic.NewFieldSort("unitLowPrice").Desc())
	case "22":
		fieldSorts = append(fieldSorts, elastic.NewFieldSort("productClassification").Desc())
		fieldSorts = append(fieldSorts, elastic.NewFieldSort("unitTotalPrice").Asc())
	case "23":
		fieldSorts = append(fieldSorts, elastic.NewFieldSort("unitTotalPrice").Desc())
	case "24":
		fieldSorts = append(fieldSorts, elastic.NewFieldSort("productClassification").Desc())
		fieldSorts = append(fieldSorts, elastic.NewFieldSort("unitMemberPrice").Asc())
	case "25":
		fieldSorts = append(fieldSorts, elastic.NewFieldSort("unitMemberPrice").Desc())
	case "26":
		fieldSorts = append(fieldSorts, elastic.NewFieldSort("productClassification").Desc())
		fieldSorts = append(fieldSorts, elastic.NewFieldSort("unitMemberTotalPrice").Asc())
	case "27":
		fieldSorts = append(fieldSorts, elastic.NewFieldSort("unitMemberTotalPrice").Desc())

	default:
		fieldSorts = append(fieldSorts, elastic.NewFieldSort("_score").Desc())
		fieldSorts = append(fieldSorts, elastic.NewFieldSort("popularityScore").Desc())
		fieldSorts = append(fieldSorts, elastic.NewFieldSort("registerDate").Desc())
	}

	return fieldSorts
}

func ProductMemberLowerSort(sort string) (fieldSorts []elastic.Sorter) {
	fieldSorts = append(fieldSorts, elastic.NewFieldSort("_score").Desc())
	fieldSorts = append(fieldSorts, elastic.NewFieldSort("popularityScore").Desc())
	fieldSorts = append(fieldSorts, elastic.NewFieldSort("registerDate").Desc())

	return
}

