		if brpsFieldName != "SKIP" && data["packageYN"] == "Y" && element.InnerHits["_bundle"].Hits.TotalHits.Value > 1 {
			resultData, highlight = utils.BrpsSettingEs2(element, brpsFieldName, 0, data["quickPriceYN"])
		} else {
			json.Unmarshal([]byte(element.Source), &resultData)
		}

		//하이라이팅 있을시 교체
		if len(highlight) > 0 {
			for k, v := range highlight {
				resultData[k] = v
			}
		} else {
			if element.Highlight != nil {
				for i, value := range element.Highlight {
					resultData[i] = value[0]
				}
			}

		}

		listES := &model.ProductListES{}
		mapstructure.Decode(resultData, &listES)

		//제조사명 처리
		if listES.ProductMaker == "확인중" {
			listES.ProductMaker = ""
			listES.ProductBrand = ""
		}

		if listES.ProductMaker == listES.ProductBrand {
			listES.ProductBrand = ""
		}

		// 옵션 마크 이미지 url
		if listES.OptionMarkUrl != "" {
			listES.OptionMarkUrl = fmt.Sprintf("http://img.danawa.com/prod_img/mark/%s", listES.OptionMarkUrl)
		}

		//ES - Inner Hit에 자기자신이 항상 포함되므로 1이상일때만 번들 노출,
		// 2025 07-03 이찬호 빠른배송일 경우 번들 노출 필요 x
		if element.InnerHits["_bundle"] != nil && element.InnerHits["_bundle"].Hits.TotalHits.Value > 1 && data["quickPriceYN"] != "Y" {
			listES.BundleSize = int(element.InnerHits["_bundle"].Hits.TotalHits.Value)
			bundleList := make([]*model.Bundle, 0)

			for _, bundle := range element.InnerHits["_bundle"].Hits.Hits {

				bundleProductES := &model.BundleES{}

				json.Unmarshal([]byte(bundle.Source), &bundleProductES)

				if bundleProductES.ProductMaker == "확인중" {
					bundleProductES.ProductMaker = ""
					bundleProductES.ProductBrand = ""
				}

				if bundleProductES.ProductMaker == bundleProductES.ProductBrand {
					bundleProductES.ProductBrand = ""
				}

