func BrpsSettingEs2(searchHit *elasticSearch.SearchHit, brpsFieldName string, sort int, quickPriceYN string) (source map[string]interface{}, highlight map[string]string) {
	source = make(map[string]interface{}, 0)
	highlight = make(map[string]string, 0)

	var bundleMap map[string]interface{}
	data := make(map[string]interface{}, 0)
	json.Unmarshal([]byte(searchHit.Source), &data)

	isBbrpsFieldName := brpsFieldName == "registerDateTime" || brpsFieldName == "manufactureDate" //

	if searchHit.InnerHits["_bundle"] != nil && (data["brps"] == "R" || isBbrpsFieldName) {
		// 검색 내부 정책 : 번들 시퀀스 비교해서 대표상품 지정 숫자가 작을 수록 우선
		// 만약 같은 경우 상품코드가 낮은 상품을 대표 상품으로 지정

		tempData := make(map[string]interface{}, 0)

		bundleSize := searchHit.InnerHits["_bundle"].Hits.TotalHits.Value

		bundle := searchHit.InnerHits["_bundle"].Hits.Hits

		if reflect.ValueOf(bundle).Kind() == reflect.Slice && bundleSize > 1 {
			tempData = nil
			tempData = data

			for _, bundleList := range bundle {
				bundleMap = make(map[string]interface{})
				json.Unmarshal([]byte(bundleList.Source), &bundleMap)

				var brpsFieldTempData int
				var productBundleNameTempData string

				if tempData[brpsFieldName] != nil {
					brpsFieldTempData, _ = strconv.Atoi(fmt.Sprintf("%s", tempData[brpsFieldName]))
					productBundleNameTempData = fmt.Sprintf("%s", tempData["bundleName"])
				}
				brpsFieldBundleData, _ := strconv.Atoi(fmt.Sprintf("%s", bundleMap[brpsFieldName])) // 번들시퀀스

				productBundleNameData := fmt.Sprintf("%s", bundleMap["bundleName"]) // 번들 명

				if brpsFieldTempData > brpsFieldBundleData { //번들 시퀀스 비교
					tempData = nil
					tempData = bundleMap

					for k, v := range bundleList.Highlight {
						highlight[k] = v[0]
					}
				} else if brpsFieldTempData == brpsFieldBundleData { // 번들시퀀스가  같으면 번들명 오름차순으로 정렬 후 첫번째를 대표로 지정
					if productBundleNameTempData > productBundleNameData {
						tempData = nil
						tempData = bundleMap

						for k, v := range bundleList.Highlight {
							highlight[k] = v[0]
						}
					}
				}
			}

			//ES의 번들(Inner Hit) 따로 영역이 있어 변경된 대표만 담아 리턴
			//tempData["_bundleSize"] = bundleSize
			//tempData["_bundle"] = bundleMap

			source = tempData
		} else {

			source = data
		}
	} else if searchHit.InnerHits["_bundle"] != nil && (data["brps"] == "S" && brpsFieldName == "bundleDisplaySequence") { // 1. 인기상품순 정렬이고 인기상품노출(S)
		bundleHits := searchHit.InnerHits["_bundle"].Hits.Hits
		tempListData := data // 임시대표상품

		for idx := range bundleHits {
			bundle := make(map[string]interface{})

			json.Unmarshal([]byte(bundleHits[idx].Source), &bundle)

			var bundleScore interface{}
			var tempScore interface{}

			bundleScore = bundle["cntSave"]
			tempScore = tempListData["cntSave"]

			if bundleScore == nil && tempScore == nil {
				bundleScore = bundle["popularityScore"]
				tempScore = tempListData["popularityScore"]
			}

			dataSequence := CheckIntData(fmt.Sprintf("%s", tempListData["bundleDisplaySequence"]))
			bundleSequence := CheckIntData(fmt.Sprintf("%s", bundle["bundleDisplaySequence"]))

			//2025.07.02 이찬호
			//빠른배송 상품일 경우, 번들시퀀스가 작은 상품이 대표상품
			if quickPriceYN == "Y" {
				if bundleSequence < dataSequence {
					tempListData = bundle
				} else if bundleSequence == dataSequence { // 번들시퀀스가 같으면, 번들명비교
					listBundleName := tempListData["bundleName"]
					bundleName := bundle["bundleName"]
					if listBundleName != nil && bundleName != nil {
						switch strings.Compare(listBundleName.(string), bundleName.(string)) { // 4.번들시퀀스도 같다면, 번들명까지 비교.
						case 1:
							tempListData = bundle
							for k, v := range bundleHits[idx].Highlight {
								highlight[k] = v[0]
							}
						}
					}
				}
			}

			if bundleScore == tempScore { // 2. 리스트정렬상품(대표상품)이랑 점수가 하나라도 같으면
				if bundleSequence < dataSequence { // // 3. 번들시퀀스가 작은상품이 대표상품
					tempListData = bundle

					for k, v := range bundleHits[idx].Highlight {
						highlight[k] = v[0]
					}

				} else if bundleSequence == dataSequence { // 같으면, 번들명비교
					listBundleName := tempListData["bundleName"]
					bundleName := bundle["bundleName"]
					if listBundleName != nil && bundleName != nil {
						// The result will be 0 if a==b, -1 if a < b, and +1 if a > b.
						// -1 if a < b  250GB < 500GB, 250GB < 2TB , 250GB < 4TB
						// 0 if a==b 250GB == 250GB
						// +1 if a > b 250GB > 1TB
						switch strings.Compare(listBundleName.(string), bundleName.(string)) { // 4.번들시퀀스도 같다면, 번들명까지 비교.
						case 1:
							tempListData = bundle

							for k, v := range bundleHits[idx].Highlight {
								highlight[k] = v[0]
							}
						}
					}
				}
			} else if CheckIntData(bundleScore.(string)) > CheckIntData(tempScore.(string)) && sort == 9 { // 인기순 정렬이고, 묶음상품이 리스트정렬상품(대표상품)보다 점수가 높은경우 묶음(번들)상품이 대표
				tempListData = bundle

				for k, v := range bundleHits[idx].Highlight {
					highlight[k] = v[0]
				}
			}
		}

		source = tempListData
	} else {
		source = data
	}

